import{_ as a,o as e,c as i,af as t}from"./chunks/framework.BSym9njW.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/00-environment/fastflowlm.md","filePath":"zh/00-environment/fastflowlm.md","lastUpdated":1789547203000}'),l={name:"zh/00-environment/fastflowlm.md"};function n(d,s,p,r,h,o){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h2 id="fastflowlm-环境配置-ubuntu-24-04-xdna2" tabindex="-1">FastFlowLM 环境配置（Ubuntu 24.04 + XDNA2） <a class="header-anchor" href="#fastflowlm-环境配置-ubuntu-24-04-xdna2" aria-label="Permalink to &quot;FastFlowLM 环境配置（Ubuntu 24.04 + XDNA2）&quot;">​</a></h2><p>本节介绍在 Ubuntu 24.04 上安装 <strong>FastFlowLM（<code>flm</code>）</strong> 与 XDNA2 NPU 驱动，使后续章节可以直接 <code>flm pull</code> / <code>flm serve</code>。不经过 Lemonade。硬件对照见 <a href="./xdna2-npu">XDNA2</a>；排错见 <a href="./npu-troubleshooting">NPU 排错</a>。</p><blockquote><p>前置条件：本机是 <strong>XDNA2</strong>（Strix Halo / Kraken / Strix Point / Gorgon）。XDNA1 请停在硬件对照页。</p><p>官方文档：<a href="https://fastflowlm.com/docs/install_lin/" target="_blank" rel="noreferrer">FastFlowLM Linux</a> · <a href="https://lemonade-server.ai/flm_npu_linux.html" target="_blank" rel="noreferrer">Lemonade Linux + FLM</a>（驱动来源相同，本节只用 <code>flm</code>）</p></blockquote><hr><h3 id="本教程验证基线-2026-09-16" tabindex="-1">本教程验证基线（2026-09-16） <a class="header-anchor" href="#本教程验证基线-2026-09-16" aria-label="Permalink to &quot;本教程验证基线（2026-09-16）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">值</th></tr></thead><tbody><tr><td style="text-align:left;"><code>flm</code></td><td style="text-align:left;"><strong>1.0.5</strong>（<code>/usr/bin/flm</code>）</td></tr><tr><td style="text-align:left;">XRT</td><td style="text-align:left;"><code>libxrt-npu2</code> 2.25.0</td></tr><tr><td style="text-align:left;">驱动</td><td style="text-align:left;"><code>amdxdna-dkms</code></td></tr><tr><td style="text-align:left;">设备</td><td style="text-align:left;"><code>/dev/accel/accel0</code>，组 <code>render</code></td></tr><tr><td style="text-align:left;">固件</td><td style="text-align:left;"><strong>1.1.2.65</strong></td></tr><tr><td style="text-align:left;">IOMMU</td><td style="text-align:left;"><code>amd_iommu=on iommu=pt</code></td></tr><tr><td style="text-align:left;">memlock</td><td style="text-align:left;">unlimited</td></tr><tr><td style="text-align:left;">用户组</td><td style="text-align:left;"><code>render</code> <code>video</code></td></tr><tr><td style="text-align:left;">已验证权重</td><td style="text-align:left;"><code>gemma4-it:e4b</code> · <code>qwen3.6-moe:35b-a3b</code></td></tr></tbody></table><p>安装时请到 <a href="https://github.com/ROCm/FastFlowLM/releases" target="_blank" rel="noreferrer">FastFlowLM Releases</a> 取<strong>当前最新</strong> <code>.deb</code>，不必钉死 1.0.5。</p><hr><h3 id="_1-安装驱动与-flm" tabindex="-1">1. 安装驱动与 FLM <a class="header-anchor" href="#_1-安装驱动与-flm" aria-label="Permalink to &quot;1. 安装驱动与 FLM&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> add-apt-repository</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ppa:lemonade-team/stable</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> update</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> libxrt-npu2</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> amdxdna-dkms</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>从 <a href="https://github.com/ROCm/FastFlowLM/releases" target="_blank" rel="noreferrer">Releases</a> 下载对应发行版的 <code>.deb</code>（Ubuntu 24.04 选 <code>ubuntu24.04</code>）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ./fastflowlm</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">*</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">_ubuntu24.04_amd64.deb</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> reboot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>必须 reboot</strong>，才会切到 DKMS 模块和 1.1 固件。不要只换 firmware、不换 DKMS。</p><hr><h3 id="_2-配置-iommu" tabindex="-1">2. 配置 IOMMU <a class="header-anchor" href="#_2-配置-iommu" aria-label="Permalink to &quot;2. 配置 IOMMU&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">tr</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &#39; &#39;</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &#39;\\n&#39;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> &lt; </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">/proc/cmdline</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">grep</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> iommu</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>必须同时有 <code>amd_iommu=on</code> 和 <code>iommu=pt</code>。否则 <code>flm</code> 会出现 SVA bind <strong>-19</strong>。缺了就改 GRUB：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> nano</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /etc/default/grub</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在 <code>GRUB_CMDLINE_LINUX_DEFAULT</code> 中加入 <code>amd_iommu=on iommu=pt</code>，然后：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> update-grub</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> reboot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>⚠️ 部分「拉大 GTT」配方会写 <code>amd_iommu=off</code>，和 NPU <strong>互斥</strong>。要跑 FastFlowLM 就必须用 <code>iommu=pt</code>。</p></blockquote><hr><h3 id="_3-权限与-memlock" tabindex="-1">3. 权限与 memlock <a class="header-anchor" href="#_3-权限与-memlock" aria-label="Permalink to &quot;3. 权限与 memlock&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> usermod</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -aG</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> render,video</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &quot;</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">$USER</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">&quot;</span><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">   # 一次；重新登录后生效</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>ulimit -l</code> 必须是 <code>unlimited</code>。若不是，写入 <code>/etc/security/limits.conf</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>*    soft    memlock    unlimited</span></span>
<span class="line"><span>*    hard    memlock    unlimited</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>重新登录后再查：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ls</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -l</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /dev/accel/accel0</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ulimit</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h3 id="_4-校验" tabindex="-1">4. 校验 <a class="header-anchor" href="#_4-校验" aria-label="Permalink to &quot;4. 校验&quot;">​</a></h3><p>每次跑 <code>flm</code> 前先清掉 ROCm 用户态路径：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">flm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> validate</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">flm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> list</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --filter</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> installed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>flm validate</code> 期望类似：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>[Linux]  NPU: /dev/accel/accel0</span></span>
<span class="line"><span>[Linux]  NPU FW Version: 1.1.2.65</span></span>
<span class="line"><span>[Linux]  Memlock Limit: infinity</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>仓库脚本（可选）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">bash</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> src/npu/scripts/check_flm_npu.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>source /opt/rocm</code> 后再跑 <code>flm</code> 会变成 <code>No such device with index &#39;0&#39;</code>。</p><hr><h3 id="_5-端口与互斥" tabindex="-1">5. 端口与互斥 <a class="header-anchor" href="#_5-端口与互斥" aria-label="Permalink to &quot;5. 端口与互斥&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">值</th></tr></thead><tbody><tr><td style="text-align:left;"><code>flm serve</code></td><td style="text-align:left;">本教程用 <strong>8219</strong>（官方默认端口可能不同）</td></tr><tr><td style="text-align:left;">同时 LLM</td><td style="text-align:left;"><strong>1 路</strong>（NPU 串行）</td></tr><tr><td style="text-align:left;">与 Lemonade</td><td style="text-align:left;">Lemonade 若 <code>load</code> 了 FLM 模型，先 <code>lemonade unload</code> 再 <code>flm serve</code></td></tr></tbody></table><p>下一步：</p><ul><li><a href="/hello-rocm/zh/01-deploy/gemma4/fastflowlm-npu-deploy">Gemma 4 FastFlowLM 部署</a></li><li><a href="/hello-rocm/zh/01-deploy/qwen36/fastflowlm-npu-deploy">Qwen3.6 FastFlowLM 部署</a></li><li><a href="./lemonade">Lemonade 环境</a>（要 Web UI / 统一 13305 端口时）</li></ul>`,42)])])}const u=a(l,[["render",n]]);export{k as __pageData,u as default};
